_SUPPORTED_DPRS = (1.0, 1.25, 1.5, 1.75, 2.0, 2.5, 3.0)
_FALLBACK_ICON_NAME = "circle-help"
_WARNED_MISSING_ICONS: set[str] = set()


def _icon_from_svg(svg_str: str, size: int) -> QIcon:
    """Build a multi-DPR icon so Qt can select the target screen variant."""

    renderer = QSvgRenderer(QByteArray(svg_str.encode("utf-8")))
    icon = QIcon()
    for dpr in _SUPPORTED_DPRS:
        physical = max(1, round(int(size) * dpr))
        pixmap = QPixmap(physical, physical)
        pixmap.fill(Qt.transparent)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        renderer.render(painter)
        painter.end()
        pixmap.setDevicePixelRatio(dpr)
        icon.addPixmap(pixmap)
    return icon


@lru_cache(maxsize=128)
def _render_icon(name: str, size: int, color: str) -> QIcon:
    """内部缓存渲染器 — 相同参数不重复渲染多 DPR SVG。"""
    svg_str = _SVG.get(name)
    if not svg_str:
        return QIcon()

    svg_str = svg_str.replace('stroke="currentColor"', f'stroke="{color}"')
    svg_str = svg_str.replace('fill="currentColor"', f'fill="{color}"')

    return _icon_from_svg(svg_str, size)


def get_application_icon() -> QIcon:
    """Return the fixed product icon used by Windows shell surfaces."""

    icon_path = Path(__file__).parent / "app_icon.png"
    icon = QIcon(str(icon_path))
    return icon if not icon.isNull() else get_app_logo(256)


def get_icon(
    name: str,
    size: int = 20,
    color: str | None = None,
    *,
    strict: bool = False,
) -> QIcon:
    """将 Lucide SVG 转为 QIcon，可指定尺寸和颜色。

    内部使用 LRU 缓存，主题切换时需调用 invalidate_icon_cache()。

    Args:
        name: 图标名（_SVG 字典的 key）
        size: 逻辑像素尺寸
        color: hex 颜色，None 则使用主题 icon_primary
    """
    normalized_name = str(name or "").strip()
    if not normalized_name:
        return QIcon()
    if normalized_name not in _SVG:
        if strict:
            raise KeyError(f"Unknown icon name: {normalized_name}")
        if normalized_name not in _WARNED_MISSING_ICONS:
            _WARNED_MISSING_ICONS.add(normalized_name)
            _LOGGER.warning(
                "Unknown icon name %r; using %r fallback",
                normalized_name,
                _FALLBACK_ICON_NAME,
            )
        normalized_name = _FALLBACK_ICON_NAME

    if color is None:
        color = get_theme().icon_primary

    return _render_icon(normalized_name, size, color)


def get_icon_names() -> list[str]:
    """返回所有可用图标名。"""
    return list(_SVG.keys())


def is_icon_registered(name: str) -> bool:
    """Return whether ``name`` resolves to a catalog entry without fallback."""

    return str(name or "").strip() in _SVG


def invalidate_icon_cache() -> None:
    """Clear rendered pixmaps when an explicit memory reset is required."""
    _render_icon.cache_clear()


def get_app_logo(size: int = 24) -> QIcon:
    """渲染 App 专属 Logo (app_logo.svg)，双色跟随主题。

    SVG 中使用语义占位符（不依赖具体 hex 值）:
        __LOGO_DARK__  → theme.logo_dark
        __LOGO_LIGHT__ → theme.logo_light
    """

    svg_path = Path(__file__).parent / "app_logo.svg"
    if not svg_path.exists():
        return QIcon()

    svg_str = svg_path.read_text(encoding="utf-8")

    # 语义占位符替换: 不依赖具体 hex 色号
    t = get_theme()
    svg_str = svg_str.replace("__LOGO_DARK__", t.logo_dark)
    svg_str = svg_str.replace("__LOGO_LIGHT__", t.logo_light)

    return _icon_from_svg(svg_str, size)
